{
  "implementation": "import math

def solve(case):
    # Validate required fields
    required = ['sentence_vectors', 'query_vector', 'context_weight']
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    sentence_vectors = case['sentence_vectors']
    query = case['query_vector']
    w = case['context_weight']

    n = len(sentence_vectors)
    if n == 0:
        return {'ranking': [], 'scores': []}

    # Compute cosine similarities
    sims = []
    for v in sentence_vectors:
        dot = sum(a * b for a, b in zip(v, query))
        norm_v = math.sqrt(sum(a * a for a in v))
        norm_q = math.sqrt(sum(a * a for a in query))
        if norm_v == 0.0 or norm_q == 0.0:
            sims.append(0.0)
        else:
            sims.append(dot / (norm_v * norm_q))

    # Compute neighbor average for each position
    neighbor_avgs = []
    for i in range(n):
        neighbors = []
        if i > 0:
            neighbors.append(sims[i-1])
        if i < n - 1:
            neighbors.append(sims[i+1])
        if neighbors:
            avg = sum(neighbors) / len(neighbors)
        else:
            avg = 0.0
        neighbor_avgs.append(avg)

    # Blend scores and round
    scores = [(1.0 - w) * sims[i] + w * neighbor_avgs[i] for i in range(n)]
    rounded = [round(s, 6) for s in scores]

    # Create list of (score, index) pairs and sort descending by score then ascending index
    indexed = list(enumerate(rounded))
    indexed.sort(key=lambda x: (-x[1], x[0]))

    ranking = [idx for idx, _ in indexed]
    sorted_scores = [sc for _, sc in indexed]

    return {'ranking': ranking, 'scores': sorted_scores}
